PLACEHOLDER_COUNTS = {}


def build_n5_entries():
    entries = []
    for suffix, pattern, romaji, meaning, formation, usage_notes, similar, sentence_examples in N5_GRAMMAR_ENTRIES:
        entries.append({
            "id": f"bunpou_{suffix}",
            "pattern": pattern,
            "patternRomaji": romaji,
            "jlptLevel": "N5",
            "meaning": meaning,
            "formation": formation,
            "usageNotes": usage_notes,
            "similarPatterns": [f"bunpou_{s}" for s in similar],
            "sentenceExamples": [
                {"japanese": jp, "romaji": ro, "translation": tr}
                for jp, ro, tr in sentence_examples
            ],
        })
    return entries


